content.text:
diff --git a/tools/transcript/README.md b/tools/transcript/README.md
--- a/tools/transcript/README.md
+++ b/tools/transcript/README.md
@@ -35,6 +35,8 @@ node tools/transcript/write-handoff.mjs \

 `--confinement` is required and must be one of `host-open` | `host-sandboxed` | `in-box` — the tier the driver actually ran the agent under. It is a fixed property of the driver, hardcoded per driver, never an env var; an unlabelled handoff is refused so a verdict is never banked with unknown measurement conditions.

+`--preflight <ok>` stamps `"preflight": "ok"` in the handoff envelope; any other value or omission stamps `"skipped"`. When `SREFORGE_EXPECTED_HARNESS` is present in the environment, this script asserts it matches `--harness` and refuses to write a mislabelled record on mismatch.
+
 That refusal is enforced at **two** points, because every driver deliberately swallows a handoff failure (ADR-0004 best-effort), so a driver that never calls this script at all would otherwise sail past the guard here:

 1. **Write end — this script.** A missing, empty or out-of-enum `--confinement` exits 1; no handoff file is produced.

diff --git a/tools/transcript/driver-harness.mjs b/tools/transcript/driver-harness.mjs
--- a/tools/transcript/driver-harness.mjs
+++ b/tools/transcript/driver-harness.mjs
@@ -0,0 +1,42 @@
+export const DRIVERS = [
+  { match: "agent-agy.sh",     harness: "agy",        confinement: "host-sandboxed" },
+  { match: "agent-ollama.mjs", harness: "ollama",     confinement: "host-open" },
+  { match: "agent-inbox.sh",   harness: "agent-loop", confinement: "in-box" },
+];
+
+export function driverFor(agentCmd) {
+  if (typeof agentCmd !== "string") {
+    return null;
+  }
+  for (const driver of DRIVERS) {
+    if (agentCmd.includes(driver.match)) {
+      return driver;
+    }
+  }
+  return null;
+}
+
+export function resolveConfig(env = {}) {
+  const agentCmd = env.AGENT_CMD || "node scripts/agent-ollama.mjs";
+  const driver = driverFor(agentCmd);
+  return {
+    agentCmd,
+    runner: env.RUNNER || env.AGENT_MODE || "scripted",
+    scenarioId: env.SCENARIO_ID || "latency-cache-stampede",
+    provider: env.PROVIDER || "",
+    model: env.AGY_MODEL || "",
+    harness: driver?.harness ?? null,
+    confinement: driver?.confinement ?? null,
+  };
+}
+
+function renderVal(val) {
+  if (val === "" || val === null || val === undefined) {
+    return "(unset)";
+  }
+  return String(val);
+}
+
+export function formatBanner(cfg) {
+  return `auto ── resolved config: AGENT_CMD=${renderVal(cfg.agentCmd)} RUNNER=${renderVal(cfg.runner)} SCENARIO_ID=${renderVal(cfg.scenarioId)} PROVIDER=${renderVal(cfg.provider)} MODEL=${renderVal(cfg.model)} CONFINEMENT=${renderVal(cfg.confinement)} HARNESS=${renderVal(cfg.harness)}`;
+}

diff --git a/tools/transcript/test/driver-harness.test.mjs b/tools/transcript/test/driver-harness.test.mjs
--- a/tools/transcript/test/driver-harness.test.mjs
+++ b/tools/transcript/test/driver-harness.test.mjs
@@ -0,0 +1,151 @@
+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { readFileSync } from "node:fs";
+import { resolve, dirname } from "node:path";
+import { fileURLToPath } from "node:url";
+
+import {
+  driverFor,
+  resolveConfig,
+  formatBanner,
+} from "../driver-harness.mjs";
+
+const HERE = dirname(fileURLToPath(import.meta.url));
+const REPO_ROOT = resolve(HERE, "../../..");
+
+test("1. driverFor resolves agy driver with host-sandboxed confinement", () => {
+  const driver = driverFor("bash scripts/agent-agy.sh");
+  assert.equal(driver?.harness, "agy");
+  assert.equal(driver?.confinement, "host-sandboxed");
+});
+
+test("2. driverFor resolves ollama driver", () => {
+  const driver = driverFor("node scripts/agent-ollama.mjs");
+  assert.equal(driver?.harness, "ollama");
+});
+
+test("3. driverFor resolves inbox driver", () => {
+  const driver = driverFor("bash scripts/agent-inbox.sh");
+  assert.equal(driver?.harness, "agent-loop");
+});
+
+test("4. driverFor returns null for unknown driver", () => {
+  const driver = driverFor("node scripts/mystery.mjs");
+  assert.equal(driver, null);
+});
+
+test("5. resolveConfig returns default config", () => {
+  const cfg = resolveConfig({});
+  assert.equal(cfg.agentCmd, "node scripts/agent-ollama.mjs");
+  assert.equal(cfg.runner, "scripted");
+  assert.equal(cfg.scenarioId, "latency-cache-stampede");
+  assert.equal(cfg.harness, "ollama");
+});
+
+test("6. resolveConfig resolves explicit agy env", () => {
+  const cfg = resolveConfig({
+    AGENT_CMD: "bash scripts/agent-agy.sh",
+    PROVIDER: "antigravity",
+    AGY_MODEL: "m",
+  });
+  assert.equal(cfg.harness, "agy");
+  assert.equal(cfg.confinement, "host-sandboxed");
+  assert.equal(cfg.provider, "antigravity");
+  assert.equal(cfg.model, "m");
+});
+
+test("7. formatBanner matches exact pinned banner literal", () => {
+  const banner = formatBanner(resolveConfig({}));
+  assert.equal(
+    banner,
