+    banner,
+    "auto ── resolved config: AGENT_CMD=node scripts/agent-ollama.mjs RUNNER=scripted SCENARIO_ID=latency-cache-stampede PROVIDER=(unset) MODEL=(unset) CONFINEMENT=host-open HARNESS=ollama",
+  );
